SELECT tblTakeOffMonth.TakeOffMonthID, qryTakeOffStep2.Orig_Atty, Sum(qryTakeOffStep2.EarlyEarned) AS SumOfEarlyEarned, Sum(qryTakeOffStep2.TOEarned) AS SumOfTOEarned, Sum(qryTakeOffStep2.CostReimb) AS SumOfCostReimb, Sum(qryTakeOffStep2.CBHRev) AS SumOfCBHRev, Sum(qryTakeOffStep2.MKRev) AS SumOfMKRev, Sum(qryTakeOffStep2.CBHCom) AS SumOfCBHCom, Sum(qryTakeOffStep2.MTRev) AS SumOfMTRev, Sum(qryTakeOffStep2.MTCom) AS SumOfMTCom, Sum(qryTakeOffStep2.KBCom) AS SumOfKBCom, Sum(qryTakeOffStep2.MKCom) AS SumOfMKCom, Sum(Nz([EarlyEarned],0)+Nz([TOEarned],0)) AS SumOfEarned, Sum(Nz([EarlyEarned],0)+Nz([TOEarned],0)+Nz([CBHRev],0)) AS SumOfEarnedCBH, Sum(Nz([EarlyEarned],0)+Nz([TOEarned],0)+Nz([MKRev],0)) AS SumOfEarnedMK
FROM qryTakeOffStep2 INNER JOIN tblTakeOffMonth ON qryTakeOffStep2.TakeOffMonthID = tblTakeOffMonth.TakeOffMonthID
GROUP BY tblTakeOffMonth.TakeOffMonthID, qryTakeOffStep2.Orig_Atty;